 /*
 * This class is responsible for storing Dialog service class's response payload.
 */
export class DialogResponse {
  private user : boolean;
  private text : string;
  private ce : any;
  private arr : Array<any> = [];
  private payload : Object;

  constructor (text, user : boolean, ce, payload) {
    this.user = user;
    this.text = text;
    this.ce = ce;
    if (ce) {
      this.arr = [];
      for (let i = 0; i < ce.length; i++) {
        this.arr.push ({body : ce[i].body, bodySnippet : ce[i].bodySnippet, confidence : ce[i].confidence,
          highlight : ce[i].highlight, sourceUrl : ce[i].sourceUrl, title : ce[i].title});
      }
    }
    this.payload = payload;
  }

  public getText () {
    return this.text;
  }

  public isUser () {
    return this.user;
  }

  public getCe () {
    return this.arr;
  }

  public getPayload () {
    return this.payload;
  }
}

